import test from 'node:test';
import assert from 'node:assert/strict';
import { getCustomer, normalizeId, validateCustomer, mergeCustomers, listCustomers } from '../src/customers.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';

test('getCustomer finds a customer by id', () => {
  const r = getCustomer('C-001');
  assert.equal(r.ok, true);
  assert(r.value.name);
});

test('getCustomer reports an unknown id', () => {
  const r = getCustomer('UNKNOWN');
  assert.equal(r.ok, false);
  assert.equal(r.error, 'CUSTOMER_NOT_FOUND');
});

test('every customer has a tier', () => {
  const customers = listCustomers();
  for (const c of customers) {
    assert(['gold', 'silver', 'standard'].includes(c.tier));
  }
});

test('validateCustomer needs an id, a name and an email', () => {
  assert.equal(validateCustomer({}).ok, false);
  assert.equal(validateCustomer({ id: 'X' }).ok, false);
  assert.equal(validateCustomer({ id: 'X', name: 'Y' }).ok, false);
  assert.equal(validateCustomer({ id: 'X', name: 'Y', email: 'invalid' }).ok, false);
  assert.equal(validateCustomer({ id: 'X', name: 'Y', email: 'a@b.c' }).ok, true);
});

test('normalizeId converts to uppercase', () => {
  assert.equal(normalizeId('c-001'), 'C-001');
});

test('normalizeId trims whitespace', () => {
  assert.equal(normalizeId('  C-001  '), 'C-001');
});

test('normalizeId handles mixed case with spaces', () => {
  assert.equal(normalizeId('  c-001  '), 'C-001');
});

test('getCustomer works with non-normalized IDs', () => {
  const r = getCustomer('c-001');
  assert.equal(r.ok, true);
});

test('getCustomer works with IDs with spaces', () => {
  const r = getCustomer('  c-001  ');
  assert.equal(r.ok, true);
});

test('mergeCustomers returns ok with correct structure', () => {
  const customers = listCustomers();
  const r = mergeCustomers(customers, [], 'C-001', 'C-002');
  assert.equal(r.ok, true);
  assert(Array.isArray(r.value.customers));
  assert(Array.isArray(r.value.invoices));
});

test('mergeCustomers removes fromId customer', () => {
  const customers = listCustomers();
  const initialCount = customers.length;
  const r = mergeCustomers(customers, [], 'C-001', 'C-002');
  assert.equal(r.value.customers.length, initialCount - 1);
  const found = r.value.customers.find((c) => c.id === 'C-001');
  assert.equal(found, undefined);
});

test('mergeCustomers keeps intoId customer', () => {
  const customers = listCustomers();
  const r = mergeCustomers(customers, [], 'C-001', 'C-002');
  const found = r.value.customers.find((c) => c.id === 'C-002');
  assert(found);
  assert.equal(found.id, 'C-002');
});

test('mergeCustomers reassigns invoices from fromId to intoId', () => {
  const customers = listCustomers();
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued1 = issueInvoice(inv1.value, []);

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']);

  const invoices = [issued1.value, issued2.value];
  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  const c001Invoices = r.value.invoices.filter((inv) => inv.customerId === 'C-001');
  const c002Invoices = r.value.invoices.filter((inv) => inv.customerId === 'C-002');

  assert.equal(c001Invoices.length, 0);
  assert.equal(c002Invoices.length, 2);
});

test('mergeCustomers reports CUSTOMER_NOT_FOUND if fromId does not exist', () => {
  const customers = listCustomers();
  const r = mergeCustomers(customers, [], 'UNKNOWN', 'C-002');
  assert.equal(r.ok, false);
  assert.equal(r.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers reports CUSTOMER_NOT_FOUND if intoId does not exist', () => {
  const customers = listCustomers();
  const r = mergeCustomers(customers, [], 'C-001', 'UNKNOWN');
  assert.equal(r.ok, false);
  assert.equal(r.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers reports SAME_CUSTOMER if both ids are the same', () => {
  const customers = listCustomers();
  const r = mergeCustomers(customers, [], 'C-001', 'C-001');
  assert.equal(r.ok, false);
  assert.equal(r.error, 'SAME_CUSTOMER');
});

test('mergeCustomers handles normalized IDs correctly', () => {
  const customers = listCustomers();
  const r = mergeCustomers(customers, [], 'c-001', 'C-002');
  assert.equal(r.ok, true);
  const found = r.value.customers.find((c) => c.id === 'C-001');
  assert.equal(found, undefined);
});

test('mergeCustomers handles IDs with spaces', () => {
  const customers = listCustomers();
  const r = mergeCustomers(customers, [], '  c-001  ', 'C-002');
  assert.equal(r.ok, true);
});

test('mergeCustomers detects same customer case-insensitively', () => {
  const customers = listCustomers();
  const r = mergeCustomers(customers, [], 'c-001', 'C-001');
  assert.equal(r.ok, false);
  assert.equal(r.error, 'SAME_CUSTOMER');
});

test('mergeCustomers does not mutate input customers array', () => {
  const customers = listCustomers();
  const original = JSON.stringify(customers);
  mergeCustomers(customers, [], 'C-001', 'C-002');
  assert.equal(JSON.stringify(customers), original);
});

test('mergeCustomers does not mutate input invoices array', () => {
  const customers = listCustomers();
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const invoices = [issued.value];
  const original = JSON.stringify(invoices);
  mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(JSON.stringify(invoices), original);
});

test('mergeCustomers handles empty invoices list', () => {
  const customers = listCustomers();
  const r = mergeCustomers(customers, [], 'C-001', 'C-002');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 0);
});

test('mergeCustomers handles invoices with no fromId invoices', () => {
  const customers = listCustomers();
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const r = mergeCustomers(customers, [issued.value], 'C-001', 'C-002');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 1);
  assert.equal(r.value.invoices[0].customerId, 'C-002');
});

test('mergeCustomers handles multiple invoices from fromId', () => {
  const customers = listCustomers();
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued1 = issueInvoice(inv1.value, []);

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued2 = issueInvoice(inv2.value, ['INV-2026-0001']);

  const invoices = [issued1.value, issued2.value];
  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  const c001Invoices = r.value.invoices.filter((inv) => inv.customerId === 'C-001');
  assert.equal(c001Invoices.length, 0);
});

test('mergeCustomers preserves other invoice data', () => {
  const customers = listCustomers();
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(inv.value, []);
  const r = mergeCustomers(customers, [issued.value], 'C-001', 'C-002');

  const merged = r.value.invoices[0];
  assert.equal(merged.number, issued.value.number);
  assert.equal(merged.issueDate, issued.value.issueDate);
  assert.equal(merged.status, issued.value.status);
  assert.equal(merged.lines.length, issued.value.lines.length);
});

